#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    if (strlen(s1) >= MAX_LEN + 1 || strlen(s2) >= MAX_LEN + 1) {
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[256] = {0};
    int cnt2[256] = {0};
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ') continue;
        if ('A' <= c && c <= 'Z') c = (unsigned char)(c + ('a' - 'A'));
        cnt1[c]++;
    }
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ') continue;
        if ('A' <= c && c <= 'Z') c = (unsigned char)(c + ('a' - 'A'));
        cnt2[c]++;
    }
    const char *result = "ANAGRAM";
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) { result = "NOT_ANAGRAM"; break; }
    }
    puts(result);
    return 0;
}
